import csv
import io
import json

_FIELDS = ("id", "name")


def _normalize(rows):
    """Return a new list of dicts with only id/name, None/missing -> '', others -> str.

    Reads each input row once and never mutates it. Accepts one-shot iterables.
    """
    clean = []
    for row in rows:
        clean.append({key: "" if row.get(key) is None else str(row[key]) for key in _FIELDS})
    return clean


def _serialize_csv(clean):
    buffer = io.StringIO(newline="")
    writer = csv.writer(buffer, lineterminator="\n")
    writer.writerow(list(_FIELDS))
    for record in clean:
        writer.writerow([record[key] for key in _FIELDS])
    return buffer.getvalue()


def _serialize_json(clean):
    return json.dumps(clean, ensure_ascii=False, separators=(",", ":"))


_SERIALIZERS = {
    "csv": _serialize_csv,
    "json": _serialize_json,
}


def export_rows(rows, format):
    try:
        serialize = _SERIALIZERS[format]
    except (KeyError, TypeError):
        raise ValueError(f"unsupported format: {format!r}") from None
    return serialize(_normalize(rows))
